'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert');
const Y=require('../js/yahoo-season-v1.js');
const fixture=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/league_bundle_2026.json'),'utf8'));
const documentedShape=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/documented_json_shape.json'),'utf8'));
const canonical=[
  {canonicalId:'fhq_alpha',name:'Alpha Runner',pos:'RB',team:'BUF',externalIds:{yahoo:'40001'}},
  {canonicalId:'fhq_beta',name:'Beta Receiver',pos:'WR',team:'DAL',externalIds:{yahoo:'40002'}},
  {canonicalId:'fhq_gamma',name:'Gamma Tight End',pos:'TE',team:'KC',externalIds:{yahoo:'40003'}},
  {canonicalId:'fhq_delta',name:'Delta Quarterback',pos:'QB',team:'PHI',externalIds:{yahoo:'40004'}},
  {canonicalId:'fhq_alias',name:'Canonical Name',pos:'WR',team:'SEA'}
];
const profile={id:'test-profile',actualTeams:10,season:2026,settings:{teams:10,scoring:'half',passTD:6,waiverType:'faab',playoffStartWeek:15}};
const archives=[{sessionId:'draft-a',profileId:'test-profile',completed:true,draftMode:'live',slot:7,teamCount:10,history:[{id:'fhq_alpha',team:7,isUser:true},{id:'fhq_delta',team:7,isUser:true}]}];
const tests=[];function test(name,fn){tests.push({name,fn});}
test('discovers only the requested 2026 NFL league',()=>assert.deepStrictEqual(Y.normalizeLeagueList(fixture.league,{season:2026}).map(x=>x.leagueKey),['461.l.10001']));
test('parses Yahoo JSON array metadata explicitly',()=>{const leagues=Y.normalizeLeagueList(documentedShape,{season:2026});assert.strictEqual(leagues.length,1);assert.strictEqual(leagues[0].name,'Sanitized Test League');assert.strictEqual(leagues[0].teamCount,10);assert.strictEqual(leagues[0].leagueStatus,'in-season');});
test('settings reconciliation distinguishes matches and unknowns',()=>{const value=Y.reconcileSettings(profile,Y.normalizeSettings(fixture.settings));assert.strictEqual(value.fields.teamCount.status,'MATCH');assert.strictEqual(value.fields.scoringType.status,'MATCH');assert.strictEqual(value.fields.rosterSlots.status,'UNKNOWN');});
test('settings differences are surfaced without profile mutation',()=>{const before=JSON.stringify(profile),value=Y.reconcileSettings(profile,{teamCount:12,scoringType:'full-ppr'});assert.strictEqual(value.status,'DIFFERENT');assert.strictEqual(value.fields.teamCount.status,'DIFFERENT');assert.strictEqual(JSON.stringify(profile),before);});
test('stable Yahoo player IDs are authoritative',()=>{const result=Y.reconcilePlayer({yahooPlayerId:'40001',name:'Wrong Display',position:'RB'},Y.buildCanonicalIndex(canonical));assert.strictEqual(result.canonicalPlayerId,'fhq_alpha');assert.strictEqual(result.reason,'stable-yahoo-id');});
test('duplicate stable Yahoo IDs are quarantined as ambiguous',()=>{const result=Y.reconcilePlayer({yahooPlayerId:'40001',name:'Alpha Runner',position:'RB'},Y.buildCanonicalIndex([...canonical,{canonicalId:'duplicate-yahoo',name:'Other',pos:'RB',externalIds:{yahoo:'40001'}}]));assert.strictEqual(result.status,'AMBIGUOUS');assert.strictEqual(result.reason,'duplicate-stable-yahoo-id');});
test('approved aliases remain explicit',()=>{const result=Y.reconcilePlayer({name:'Source Alias',position:'WR'},Y.buildCanonicalIndex(canonical,{'Source Alias':'fhq_alias'}));assert.strictEqual(result.status,'ALIAS_MATCH');});
test('ambiguous identities never auto-map',()=>{const index=Y.buildCanonicalIndex([...canonical,{canonicalId:'duplicate',name:'Alpha Runner',pos:'RB'}]);const result=Y.reconcilePlayer({name:'Alpha Runner',position:'RB'},index);assert.strictEqual(result.status,'AMBIGUOUS');assert.ok(!result.canonicalPlayerId);});
test('unresolved identities remain unresolved',()=>assert.strictEqual(Y.reconcilePlayer({name:'Nobody Known',position:'WR'},Y.buildCanonicalIndex(canonical)).status,'UNRESOLVED'));
test('all team rosters and user team normalize',()=>{const value=Y.normalizeTeams(fixture.teams);assert.strictEqual(value.length,2);assert.strictEqual(value.find(x=>x.isUser).roster.length,2);});
test('transactions standings and matchups normalize behind stable contracts',()=>{assert.strictEqual(Y.normalizeTransactions(fixture.transactions)[0].transactionKey,'461.l.10001.tr.1');assert.strictEqual(Y.normalizeStandings(fixture.standings)[0].wins,1);assert.strictEqual(Y.normalizeMatchups(fixture.matchups).week,1);});
test('ownership has one authoritative owner per canonical player',()=>{const index=Y.buildCanonicalIndex(canonical),teams=Y.reconcileRoster(Y.normalizeTeams(fixture.teams),index),free=fixture.players.players.map(Y.normalizeYahooPlayer);const value=Y.buildOwnership(teams,free,index);assert.strictEqual(value.valid,true);assert.strictEqual(value.ownership.fhq_alpha.status,'ROSTERED_BY_USER');assert.strictEqual(value.ownership.fhq_gamma.status,'ROSTERED_BY_OPPONENT');assert.strictEqual(value.ownership.fhq_delta.status,'FREE_AGENT');});
test('ownership conflicts fail closed',()=>{const index=Y.buildCanonicalIndex(canonical),teams=Y.reconcileRoster(Y.normalizeTeams(fixture.teams),index);teams[1].roster.push(teams[0].roster[0]);assert.strictEqual(Y.buildOwnership(teams,[],index).valid,false);});
test('draft archive links only on strong evidence',()=>assert.strictEqual(Y.linkDraftArchive({archives,profileId:'test-profile',league:{teamCount:10},userTeam:{draftSlot:7}}).sessionId,'draft-a'));
test('multiple strong archives require review',()=>assert.strictEqual(Y.linkDraftArchive({archives:[...archives,{...archives[0],sessionId:'draft-b'}],profileId:'test-profile',league:{teamCount:10},userTeam:{draftSlot:7}}).status,'REVIEW_REQUIRED'));
test('roster delta is membership-only',()=>{const index=Y.buildCanonicalIndex(canonical),team=Y.reconcileRoster(Y.normalizeTeams(fixture.teams),index)[0],delta=Y.rosterDelta(archives[0],team);assert.deepStrictEqual(delta.retained,['fhq_alpha']);assert.deepStrictEqual(delta.noLongerRostered,['fhq_delta']);assert.deepStrictEqual(delta.acquiredAfterDraft,['fhq_beta']);});
test('snapshot preserves source and canonical teams separately',()=>{const snapshot=Y.buildSeasonSnapshot(fixture,{profile,canonicalPlayers:canonical,archives});const player=snapshot.teams[0].roster[0].identity;assert.strictEqual(player.sourceTeam,'BUF');assert.strictEqual(player.canonicalTeam,'BUF');assert.strictEqual(snapshot.draftLinkage.status,'LINKED');});
test('snapshot creation never mutates an archive',()=>{const before=JSON.stringify(archives);const snapshot=Y.buildSeasonSnapshot(fixture,{profile,canonicalPlayers:canonical,archives});assert.strictEqual(JSON.stringify(archives),before);assert.strictEqual(snapshot.draftOrigin.immutable,true);assert.strictEqual(snapshot.currentRoster.roster.length,2);});
test('malformed responses fail closed',()=>assert.throws(()=>Y.buildSeasonSnapshot({garbage:true},{profile,canonicalPlayers:canonical}),/stable league key/));
test('profile storage is isolated',()=>{const data=new Map(),storage={getItem:k=>data.get(k)||null,setItem:(k,v)=>data.set(k,v)};const store=Y.createStore(storage);store.write('a',{value:1});store.write('b',{value:2});assert.strictEqual(store.read('a').value,1);assert.strictEqual(store.read('b').value,2);});
test('failed sync marks stale without clearing last snapshot',()=>{const data=new Map(),storage={getItem:k=>data.get(k)||null,setItem:(k,v)=>data.set(k,v)};const store=Y.createStore(storage);store.write('a',{snapshot:{league:{name:'Kept'}},sync:{lastSuccessfulSyncAt:'prior'}});store.preserveFailure('a','offline','later');assert.strictEqual(store.read('a').snapshot.league.name,'Kept');assert.strictEqual(store.read('a').sync.status,'STALE');});
let passed=0,failures=[];for(const entry of tests){try{entry.fn();passed++;}catch(error){failures.push({name:entry.name,error:error.stack||error.message});}}
const result={passCount:passed,failCount:failures.length,failures};console.log(JSON.stringify(result));if(failures.length)process.exit(1);
